import sys, json, os; sys.path.insert(0, '.')
from docx_helpers import *
import packdata as PD
BAL = 'The balance of project funding is provided by Jalour sponsor equity, project collections and other capital sources.'
CONF = '**ALL INFORMATION IN THIS DOCUMENT, IN THE OTHER DOCUMENTS OF THIS PACK AND IN THE DATA ROOM IS CONFIDENTIAL. It is provided only under the non-disclosure agreement between the recipient and Jalour, and must not be disclosed, copied, forwarded or used for any other purpose.**'
def build_dd_combined(path, Te=62.5):
    C = PD.build_combined(Te); T = C['T']; G, L = C['GS'], C['LA']; PJ = [('Green Square', G), ('L\'avenir', L)]; A = C['A']; S1 = C['B']['S1']; S2 = C['B']['S2']; S3 = C['B']['S3']; sp = C['sponsor']; S = sp['scen']; ai = A['inv']
    mult = G['B']['mult']; NAME = 'Green Square and L\'avenir'
    def one(toc=None):
        d = Doc(f'{NAME} - Due Diligence Memorandum (EGP 125 million combined)', f'Jalour Developments  |  {NAME} Due Diligence Memorandum  |  Strictly private and confidential'); dd = d.d
        for _ in range(5): dd.add_paragraph()
        d.p('STRICTLY PRIVATE AND CONFIDENTIAL', bold=True, size=10, color=BRASS)
        d.p(NAME, bold=True, size=32, color=NAVY, after=2); d.p('Due Diligence Memorandum', bold=True, size=18, color=NAVY, after=6)
        d.p('Private placement of EGP 125 million: EGP 62.5 million in each project. Companion to the Investment Memorandum and Financial Annex.', size=12, after=30)
        d.p('ALL INFORMATION IN THIS DOCUMENT IS CONFIDENTIAL AND SUBJECT TO THE NON-DISCLOSURE AGREEMENT.', bold=True, size=9.5, color=BRASS, after=8)
        d.p('Issued by Jalour Developments, a subsidiary of Al Jalal Holding, Cairo. October 2026.', size=10.5, color=GREY)
